function promo(){return '<aside class="promo"><p class="eyebrow">原创 · 妙泠</p><h2>心动之外，也欢迎来找我。</h2><p>有玄梦业务需求，或想体验更多梦角趣味问卷、互动小程序，可以联系我了解。</p><strong>微信：ALing77720</strong></aside>'}
function home(){app.innerHTML='<div class="heart">♡</div><p class="eyebrow">ALMOST LOVE / 暧昧试探局</p><h1>有些话，<br>只差你再靠近一点。</h1><p class="muted">十二次试探，看你们怎样从舍不得说，走到舍不得放手。每次回应，都会被认真接住。</p><p>12 个情境 · 即时回应 · 你的暧昧说明书</p><form><label>你的昵称<input id="me" maxlength="12" required placeholder="故事中的你"></label><label>梦角的名字<input id="love" maxlength="12" required placeholder="想靠近的那个人"></label><label>对方的表达风格<select id="tone"><option>克制</option><option>温柔</option><option>狡黠</option><option>直球</option></select></label><small>双方均为成年人。所有选择都允许慢一点，喜欢不需要勉强。</small><button class="primary">开始这场试探 →</button></form>'+promo();app.querySelector('form').onsubmit=e=>{e.preventDefault();me=document.querySelector('#me').value.trim();love=document.querySelector('#love').value.trim();tone=document.querySelector('#tone').value;if(!me||!love)return;step=0;answers=[];quiz()}}
function quiz(){const q=scenes[step];app.innerHTML=`<p class="eyebrow">${String(step+1).padStart(2,'0')} / 12 · ${esc(me)} × ${esc(love)}</p><div class="progress"><div style="width:${(step+1)/12*100}%"></div></div>${step===1?`<small>上一次，${esc(love)}记住了你说的那句话。</small>`:''}<h2>${q[0].replaceAll('对方',esc(love))}</h2><div id="choices">${q[1].map((s,i)=>`<button class="option" data-i="${i}">${'ABCD'[i]}　${s}</button>`).join('')}</div><div id="reply"></div><button id="back">${step?'← 上一个情境':'← 返回开场'}</button>`;app.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>choose(+b.dataset.i));document.querySelector('#back').onclick=()=>{if(step){step--;quiz()}else home()};if(answers[step]!==undefined)choose(answers[step]);window.scrollTo(0,0)}
function choose(i){answers[step]=i;app.querySelectorAll('[data-i]').forEach(b=>{b.disabled=false;b.setAttribute('aria-pressed',String(+b.dataset.i===i));b.style.borderColor=+b.dataset.i===i?'#f6d1db':'#75515e'});const text=replies[step][i][voices.indexOf(tone)];document.querySelector('#reply').innerHTML=`<div class="response">${esc(text.replaceAll('对方',love).replaceAll('那人',love))}</div><button class="primary" id="next">${step===11?'翻开你们的故事':'把这一刻继续下去 →'}</button>`;document.querySelector('#next').onclick=()=>{if(step===11)result();else{step++;quiz()}}}
function result(){let n=[0,0,0,0];answers.forEach(i=>n[i]++);let k=n.indexOf(Math.max(...n));const titles=['把喜欢说给你听','慢慢靠近，也很动人','嘴上试探，心先投降','留出距离，才敢靠近'];const desc=['你更偏爱清楚的心意。主动邀约、认真告白、及时回应，会让你愿意交出一点勇气。','你重视那些没有声张的小事。被记住喜欢的口味，比盛大的保证更容易让你心软。','你享受有来有回的试探。玩笑是靠近的台阶，但真正让你停下的，是玩笑后面的真心。','你希望靠近可以商量。对方愿意询问、尊重节奏，你才更容易安心地走近。'];app.innerHTML=`<div class="result"><p class="eyebrow">YOUR ALMOST LOVE</p><p>${esc(me)} × ${esc(love)}</p><h1>${titles[k]}</h1><p class="tags">${['坦率回应','细节偏爱','暧昧拉扯','尊重节奏'][k]} · ${tone}风格</p></div><h2>你怎样被打动</h2><p>${desc[k]}</p><h2>你们已经写下的默契</h2><p>牵手时，你选择：${scenes[5][1][answers[5]]}<br>拥抱时，你选择：${scenes[9][1][answers[9]]}<br>意见不同时，你选择：${scenes[8][1][answers[8]]}</p><h2>你们的故事 · 雨停以前</h2><div class="ending-story">${endingStory().split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div><h2>你可以接着写的三个片段</h2><p>① ${esc(love)}记住了一句你以为只是随口说的话。<br>② 一次玩笑说到一半，忽然有人先认真。<br>③ 你说想慢一点，对方第一次学会把等待说成邀请。</p><small>结果由全部十二次选择综合形成，是娱乐性的偏好整理，不是心理诊断，也不代表梦角的真实想法。称谓与身份不限定性别。</small><button class="primary" id="again">再试一次</button>${promo()}`;document.querySelector('#again').onclick=home;window.scrollTo(0,0)}home();
